import org.jsoup.nodes.Element;
import org.jsoup.parser.*;
import org.junit.Before;
import org.junit.Test;

import java.io.StringReader;

import static org.junit.Assert.*;

public class XmlTreeBuilderTest {
    private XmlTreeBuilder xmlTreeBuilder;
    private Parser parser;
    private String baseUri;

    @Before
    public void setup() {
        xmlTreeBuilder = new XmlTreeBuilder();
        parser = Parser.xmlParser();
        baseUri = "http://example.com/";
    }

    @Test
    public void initialiseParseTest() {
        StringReader input = new StringReader("<root></root>");
        xmlTreeBuilder.initialiseParse(input, baseUri, parser);
        // check if the parse has been initialised correctly
    }

    @Test
    public void parseReaderAndStringTest() {
        StringReader input = new StringReader("<root></root>");
        // test that parse correctly returns a Document
        assertNotNull(xmlTreeBuilder.parse(input, baseUri));
    }

    @Test
    public void parseTwoStringsTest() {
        String input = "<root></root>";
        // test that parse correctly returns a Document
        assertNotNull(xmlTreeBuilder.parse(input, baseUri));
    }

    @Test
    public void newInstanceTest() {
        assertNotNull(xmlTreeBuilder.newInstance());
    }

    @Test
    public void processTokenTest() {
        Token.StartTag token = new Token.StartTag();
        token.nameAttr("testToken");
        assertTrue(xmlTreeBuilder.process(token));
    }

    @Test
    public void insertNodeTest() {
        Element element = new Element("dummy");
        xmlTreeBuilder.insertNode(element);
        // check if the node has been inserted correctly
    }

    @Test
    public void insertNodeWithTokenTest() {
        Element element = new Element("dummy");
        Token.StartTag token = new Token.StartTag("dummy");
        xmlTreeBuilder.insertNode(element, token);
        // check if the node has been inserted correctly
    }

    @Test
    public void insertTokenTest() {
        Token token = new Token.Comment();
        xmlTreeBuilder.insert(token);
        // check if the token has been inserted correctly
    }

    @Test
    public void popStackToCloseTest() {
        Token.EndTag token = new Token.EndTag();
        token.nameAttr("closingTag");
        xmlTreeBuilder.insert(token);
        xmlTreeBuilder.popStackToClose(token);
        // check if stack is popped and tag is closed
    }

    @Test
    public void parseFragmentTest() {
        String inputFragment = "<fragment></fragment>";
        // Test that parseFragment correctly returns a list of nodes
        assertNotNull(xmlTreeBuilder.parseFragment(inputFragment, baseUri, parser));
    } 

    @Test
    public void parseFragmentWithContextTest() {
        Element context = new Element("context");
        String inputFragment = "<fragment context='context'></fragment>";
        // Test that parseFragment correctly returns a list of nodes
        assertNotNull(xmlTreeBuilder.parseFragment(inputFragment, context, baseUri, parser));
    }
}
